<script setup>
const confirm=window.confirm.bind(window);
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';
import {Download,RefreshCw,LockKeyhole,BookOpenText,ArrowLeft,Trash2,WifiOff,Check} from 'lucide-vue-next';
import {api} from '@/services/api.js';
import {vaultData,enableVault,unlockVault,lockVault,closeVault,mutateVault,vaultBytes,pendingLogout,storageMessage} from '@/services/offline/vault.js';
import {downloadTask,saveLocal,syncDrafts,syncLabels,confirmConflict} from '@/services/offline/learning.js';
import {useLearning} from '@/store.js';
const store=useLearning(),user=ref(null),data=ref(vaultData()),username=ref(''),phrase=ref(''),confirmPhrase=ref(''),busy=ref(false),error=ref(''),notice=ref(''),connected=ref(false),tasks=ref([]),selected=ref(''),question=ref(''),answer=ref(''),reason=ref(''),position=ref(''),retain=ref(false),bytes=ref(0),progress=ref(null),setup=ref(false),readingIndex=ref(0),readingTab=ref('read');
const active=computed(()=>data.value?.packages.find(p=>p.taskId===selected.value)),pending=computed(()=>data.value?.operations.filter(o=>o.status!=='synced')||[]),expired=computed(()=>active.value&&Date.now()>Date.parse(active.value.offlineUntil));
async function refresh(){data.value=vaultData();bytes.value=data.value?await vaultBytes(data.value.owner.username):0;}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();await refresh()}catch(e){error.value=storageMessage(e)}finally{busy.value=false;progress.value=null}}
async function probe(){try{const r=await api.me();user.value=r.user;connected.value=true;if(vaultData()&&vaultData().owner.id!==r.user.id){lockVault();data.value=null;selected.value="";}if(r.user.role==='student'){tasks.value=await api.request('/offline/tasks');if(!username.value)username.value=r.user.username}}catch(e){connected.value=false;if(e.status===401){user.value=null;if(data.value)error.value='请在线登录原账号后同步，本机草稿保留。';}} }
function networkDown(){connected.value=false}
onMounted(probe);window.addEventListener('focus',probe);window.addEventListener('online',probe);window.addEventListener('offline',networkDown);onBeforeUnmount(()=>{window.removeEventListener('focus',probe);window.removeEventListener('online',probe);window.removeEventListener('offline',networkDown)});
async function unlock(){await run(async()=>{if(setup.value){if(!connected.value||user.value?.role!=='student')throw Error('请先在线登录学生账号。');if(phrase.value!==confirmPhrase.value)throw Error('两次离线口令不一致。');await enableVault(user.value,phrase.value)}else await unlockVault(username.value,phrase.value,connected.value?user.value:null);phrase.value=confirmPhrase.value='';});}
function open(pkg){selected.value=pkg.taskId;question.value=pkg.questions[0]?.id||'';position.value=pkg.drafts.lessonPosition?.blockId||'';readingIndex.value=Math.max(0,pkg.blocks.findIndex(b=>b.id===position.value));readingTab.value=pkg.blocks.length?'read':'practice';restoreQuestion()}
function restoreQuestion(){const d=active.value?.drafts.questions[question.value]||{};answer.value=d.answer||'';reason.value=d.reason||''}
async function save(){await run(async()=>{await saveLocal(active.value,question.value,{answer:answer.value,reason:reason.value,helped:active.value.drafts.questions[question.value]?.helped});notice.value='已保存到本机 · 等待同步';});}
async function moveReading(delta){const next=readingIndex.value+delta;if(next<0||next>=active.value.blocks.length)return;readingIndex.value=next;position.value=active.value.blocks[next].id;if(!active.value.readOnly)await savePosition();}
async function savePosition(){await run(async()=>{await saveLocal(active.value,'@position',{position:position.value});notice.value='学习位置已保存到本机';});}
async function sync(){await run(async()=>{const r=await syncDrafts(refresh);connected.value=true;notice.value=`已同步 ${r.synced} 条 · 冲突 ${r.conflicts} 条 · 失败 ${r.failed} 条`;});}
async function resumeOnline(){await run(async()=>{const me=await api.me();if(me.user.id!==data.value.owner.id)throw Error('请登录本机草稿对应的原账号。');store.user=me.user;await store.load();if(store.status!=='ready')throw Error(store.error);location.hash='/learn?task='+active.value.taskId;});}
async function exit(){await run(async()=>{if(!retain.value&&!confirm('退出将清除此账号的本机下载及草稿；未同步内容将无法恢复。继续？'))return;await closeVault({retain:retain.value,username:data.value?.owner.username});await pendingLogout(true);try{await api.logout();await pendingLogout(false)}catch{}user.value=null;connected.value=false;selected.value='';store.user=null;store.status='unauthenticated';notice.value=retain.value?'已退出，保留的加密下载需要离线口令解锁':'已退出并清除本机内容';});}
function exportCopy(op){const blob=new Blob([JSON.stringify(op,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='学习草稿-'+op.taskId+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function deletePackage(pkg){if(!confirm('删除此下载和对应本机草稿？未同步内容将无法恢复。'))return;await run(async()=>{await mutateVault(d=>{d.packages=d.packages.filter(p=>p.taskId!==pkg.taskId);d.operations=d.operations.filter(o=>o.taskId!==pkg.taskId)});if(selected.value===pkg.taskId)selected.value='';});}
</script>
<template>
 <div class="offline-screen">
  <header class="offline-header"><a href="#/home" class="offline-brand"><BookOpenText :size="24"/>师承智学</a><div class="exam-toolbar"><span role="status">{{connected?'学习服务已连接':'离线 · 仅使用本机下载'}}</span><Button variant="ghost" :disabled="busy" aria-label="检查学习服务" @click="probe"><RefreshCw :size="16"/></Button><a href="#/login">在线登录</a></div></header>
  <div class="offline-content"><PageHeading title="离线学习"><template v-if="data"><Button :disabled="busy" @click="sync"><RefreshCw :size="16"/>同步进度</Button><Button variant="outline" :disabled="busy" @click="lockVault();data=null;selected='' "><LockKeyhole :size="16"/>锁定</Button></template></PageHeading>
  <p v-if="error" class="form-error" role="alert">{{error}}</p><p v-if="notice" class="exam-notice" role="status">{{notice}}</p>
  <Surface v-if="!data" class="offline-unlock"><h2>{{setup?'首次离线学习':'打开离线课程'}}</h2><form @submit.prevent="unlock"><label class="field-label" for="offline-user">账号</label><Input id="offline-user" v-model="username" autocomplete="username" :disabled="setup" required/><label class="field-label" for="offline-phrase">离线口令 <InfoTip>独立口令至少8位，不保存登录密码。下载有效期72小时；忘记口令只能清除本机副本重新下载。</InfoTip></label><Input id="offline-phrase" v-model="phrase" type="password" autocomplete="off" minlength="8" required/><template v-if="setup"><label class="field-label" for="offline-confirm">确认离线口令</label><Input id="offline-confirm" v-model="confirmPhrase" type="password" autocomplete="off" required/></template><Button type="submit" :disabled="busy">{{busy?'正在处理…':setup?'启用并加密保存':'解锁'}}</Button><Button type="button" variant="ghost" @click="setup=!setup;if(setup&&user)username=user.username">{{setup?'已有下载，解锁':'首次使用，设置离线口令'}}</Button></form></Surface>
  <template v-else>
   <div class="offline-summary"><strong>{{data.packages.length}} 个已下载课时</strong><span>{{(bytes/1024/1024).toFixed(2)}} MB</span><span>{{pending.length}} 条待同步</span><InfoTip>离线保存不产生正式作答、核验或成绩。AI、课堂、考试、发布与提交需要联网。</InfoTip></div>
   <Surface v-if="connected&&user?.id===data.owner.id" class="offline-download"><label for="offline-task">下载课时</label><select id="offline-task" :disabled="busy"><option v-for="t in tasks" :key="t.id" :value="t.id">{{t.title}}{{t.readOnly?' · 仅阅读':''}}</option></select><Button :disabled="busy||!tasks.length" @click="run(async()=>{await downloadTask($el.querySelector('#offline-task').value,p=>progress=p);notice='课时已下载，可断网阅读'})"><Download :size="16"/>下载课时</Button><span v-if="progress" role="status">{{progress.done}} / {{progress.total}}</span></Surface>
   <div class="offline-layout"><aside><button v-for="p in data.packages" :key="p.taskId" class="exam-paper-link" :aria-current="selected===p.taskId?'page':undefined" @click="open(p)"><strong>{{p.title}}</strong><span>{{new Date(p.downloadedAt).toLocaleDateString('zh-CN')}} 下载</span></button><p v-if="!data.packages.length" class="empty-state">联网选择课时并下载</p></aside>
    <Surface v-if="active" class="offline-reader"><div class="exam-toolbar"><h2>{{active.title}}</h2><Button variant="ghost" :disabled="busy" @click="deletePackage(active)"><Trash2 :size="16"/>删除下载</Button></div><p v-if="expired" class="form-error">离线授权已到期，请联网重新下载。原草稿仍可查看和导出。</p><template v-if="!expired"><div class="student-offline-tabs"><AppTabs v-model="readingTab" :items="[{value:'read',label:'课时内容'},{value:'practice',label:'做练习'}]"/><InfoTip v-if="active.goal" label="本课目标">{{active.goal}}</InfoTip></div><template v-if="readingTab==='read'"><div class="student-offline-position"><span>{{readingIndex+1}} / {{active.blocks.length}}</span></div><article v-for="b in active.blocks.filter((_,i)=>i===readingIndex)" :key="b.id" class="curriculum-block"><h3>{{b.title}}</h3><p class="preserve-lines curriculum-prose">{{b.content}}</p><img v-if="b.imageUrl" :src="active.resources[b.imageUrl]" :alt="b.imageAlt||b.title"/><Button variant="ghost" :disabled="busy||active.readOnly" @click="position=b.id;savePosition()">{{position===b.id?'已读到这里':'读到这里'}}</Button></article><div class="student-offline-next"><Button variant="ghost" :disabled="readingIndex===0" @click="moveReading(-1)">上一节</Button><Button v-if="readingIndex<active.blocks.length-1" @click="moveReading(1)">下一节</Button><Button v-else @click="readingTab='practice'">开始练习</Button></div><p v-if="!active.blocks.length" class="empty-state">本任务只有练习题。<Button @click="readingTab='practice'">开始练习</Button></p></template><template v-if="readingTab==='practice'&&active.questions.length"><label for="offline-question" class="field-label">选择题目</label><select id="offline-question" v-model="question" @change="restoreQuestion"><option v-for="q in active.questions" :key="q.id" :value="q.id">{{q.index+1}}. {{q.prompt}} {{q.equation}}</option></select><p class="math-equation">{{active.questions.find(q=>q.id===question)?.equation}}</p><img v-if="active.questions.find(q=>q.id===question)?.imageUrl" :src="active.resources[active.questions.find(q=>q.id===question).imageUrl]" alt="题图"/><label for="offline-answer" class="field-label">答案</label><Input id="offline-answer" v-model="answer" :readonly="active.readOnly||busy"/><label for="offline-reason" class="field-label">解题过程</label><Textarea id="offline-reason" v-model="reason" :readonly="active.readOnly||busy"/><Button :disabled="busy||active.readOnly" @click="save">保存本机草稿</Button><Button v-if="connected" variant="outline" :disabled="busy" @click="resumeOnline">回到在线学习</Button></template></template></Surface><Surface v-else><div class="empty-state">选择已下载课时，继续学习</div></Surface>
   </div>
   <details v-if="data.operations.length" class="study-disclosure offline-operations"><summary>本机草稿 · {{pending.length}} 条待处理</summary><article v-for="op in data.operations" :key="op.operationId"><div><strong>{{data.packages.find(p=>p.taskId===op.taskId)?.title}}</strong><span>{{syncLabels[op.status]}}</span></div><p>{{op.questionId==='@position'?'学习位置':op.answer+' · '+op.reason}}</p><template v-if="op.conflict"><p class="form-error">{{op.conflict.message}}</p><div class="offline-compare"><div><h3>本机内容</h3><p>{{op.answer}} {{op.reason}}</p></div><div><h3>服务器内容</h3><p>{{op.conflict.serverDrafts?.questions?.[op.questionId]?.answer||'暂无'}} {{op.conflict.serverDrafts?.questions?.[op.questionId]?.reason}}</p></div></div><Button v-if="op.conflict.allowRetry" :disabled="busy" variant="outline" @click="run(async()=>{if(confirm('确认保留本机内容，并以刚读取的服务器版本重新同步？')){await confirmConflict(op.operationId);await syncDrafts(refresh)}})">确认后重新同步</Button></template><Button variant="ghost" @click="exportCopy(op)">保存本地副本</Button></article></details>
   <footer class="offline-footer"><label><input v-model="retain" type="checkbox"/>退出时保留加密下载</label><Button variant="outline" :disabled="busy" @click="exit">锁定并退出</Button><Button variant="ghost" :disabled="busy" @click="run(async()=>{if(confirm('清除此账号全部本机下载和未同步草稿？此操作无法撤销。')){await closeVault();selected=''}})">清除全部下载</Button></footer>
  </template>
 </div></div>
</template>
